// Builds the generated parts of the skill from the drawing engine's source, so there is one engine: the contract for
// Node (scripts/contract.mjs), the player page with the engine and the fonts inside (assets/player.html), the recipe
// guide, the molds and hooks, the examples, and assets/VERSION. Where the sources are is in tools/sources.json (kept
// out of git; see sources.example.json). Run: npm run assets. Never edit the generated files by hand.
import { build } from 'esbuild'
import { execFileSync } from 'node:child_process'
import { copyFileSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, symlinkSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const skill = resolve(here, '../skills/chalk-talk')
const config = join(here, 'sources.json')
if (!existsSync(config)) {
  console.error('✗ tools/sources.json is missing: copy sources.example.json and point it at the engine and guide sources.')
  process.exit(1)
}
const sources = JSON.parse(readFileSync(config, 'utf8'))
const at = (p) => resolve(here, p)
const engine = at(sources.engine)
const drawing = join(engine, 'drawing')

// The examples published with the skill: generic topics only.
const EXAMPLES = ['caverna', 'estoicismo', 'fila', 'juros', 'pitagoras', 'requisicao']

// A source must be committed, so VERSION says exactly what the skill was built from.
function pinned(file) {
  const dir = existsSync(file) && !file.endsWith('.md') ? file : dirname(file)
  if (execFileSync('git', ['-C', dir, 'status', '--porcelain', '--', file], { encoding: 'utf8' }).trim()) {
    throw new Error(`${file} has uncommitted changes: commit them first.`)
  }
  return execFileSync('git', ['-C', dir, 'describe', '--tags', '--always'], { encoding: 'utf8' }).trim()
}
const version = pinned(drawing)
const banner = `// GENERATED by tools/assets.mjs from the drawing engine ${version}. Do not edit.`

// tools/.engine points at the engine, for the typecheck (tsconfig.json) and for bundling the player.
rmSync(join(here, '.engine'), { force: true })
symlinkSync(engine, join(here, '.engine'))

// The contract, for scripts/build.mjs: plain ESM, no dependency; esbuild's file-path comments left out.
const contract = await build({
  stdin: {
    contents: `export { validateScene, chaptersFor, defaultValues } from './recipe'\nexport { PROP_NAMES, PROP_ALIASES } from './props'\n`,
    resolveDir: drawing,
    loader: 'ts',
  },
  bundle: true, format: 'esm', platform: 'node', target: 'node18', write: false, logLevel: 'warning',
})
const code = contract.outputFiles[0].text.split('\n').filter((l) => !/^\/\/ .*\.ts$/.test(l)).join('\n')
writeFileSync(join(skill, 'scripts/contract.mjs'), `${banner}\n${code}`)

// The player: engine + page code in one script.
const js = await build({
  entryPoints: [join(here, 'player/player.ts')],
  bundle: true, format: 'iife', target: 'es2020', minify: true, write: false, logLevel: 'warning',
  alias: { '@engine': drawing },
  nodePaths: [join(engine, 'node_modules'), join(here, 'node_modules')],
})
const script = js.outputFiles[0].text
if (/<\/script/i.test(script)) throw new Error('The player script contains "</script": it would end the page early.')

const font = (pkg, file) => readFileSync(join(engine, 'node_modules/@fontsource', pkg, 'files', file)).toString('base64')
const face = (family, weight, data) =>
  `@font-face{font-family:'${family}';font-style:normal;font-weight:${weight};font-display:block;src:url(data:font/woff2;base64,${data}) format('woff2')}`
const fonts = [
  face('Caveat', 700, font('caveat', 'caveat-latin-700-normal.woff2')),
  face('Shantell Sans', 400, font('shantell-sans', 'shantell-sans-latin-400-normal.woff2')),
  face('Shantell Sans', 700, font('shantell-sans', 'shantell-sans-latin-700-normal.woff2')),
].join('\n')

const fill = { VERSION: version, FONTS: fonts, CSS: readFileSync(join(here, 'player/player.css'), 'utf8'), JS: script }
const page = readFileSync(join(here, 'player/template.html'), 'utf8').replace(/\{\{(VERSION|FONTS|CSS|JS)\}\}/g, (_, k) => fill[k])
if (!page.includes('{{RECIPE}}')) throw new Error('The template lost its {{RECIPE}} slot.')
writeFileSync(join(skill, 'assets/player.html'), page)

// How to write a recipe, the molds and the hooks: the same texts the engine's app uses, so both teach one contract.
const swap = (text, from, to) => {
  if (!text.includes(from)) throw new Error(`The source text changed; update tools/assets.mjs: «${from.slice(0, 60)}»`)
  return text.replace(from, () => to)
}
const guide = at(sources.guide)
const guideVersion = pinned(guide)
let recipe = readFileSync(guide, 'utf8').replace(/^---[\s\S]*?---\n/, '')
recipe = swap(recipe, 'The app draws them on screen', 'The player draws them')
recipe = swap(recipe, 'is in {{language}}', "is in the person's language")
recipe = swap(recipe, 'Answer only the recipe, as JSON.', 'Save the recipe as a .json file and run scripts/build.mjs on it.')
const refs = at(sources.references)
const refsVersion = pinned(refs)
const ref = (f) => readFileSync(join(refs, f), 'utf8')
const generated = `<!-- GENERATED by tools/assets.mjs. Do not edit. -->\n`
writeFileSync(join(skill, 'references/recipe.md'), generated + '# Writing the recipe\n\n' + recipe)
writeFileSync(join(skill, 'references/molds.md'), generated + swap(ref('moldes.md'), 'Examples of each, already drawn: the platform recipes', 'Examples of each, already drawn, in references/examples/: the recipes'))
writeFileSync(join(skill, 'references/hooks.md'), generated + ref('ganchos.md'))

// The examples.
const examples = join(skill, 'references/examples')
rmSync(examples, { recursive: true, force: true })
mkdirSync(examples, { recursive: true })
for (const name of EXAMPLES) copyFileSync(join(drawing, 'scenes', `${name}.json`), join(examples, `${name}.json`))

writeFileSync(join(skill, 'assets/VERSION'), `engine ${version}\nguide ${guideVersion}\nmolds-and-hooks ${refsVersion}\n`)
console.log(`✓ assets from the engine ${version}: player.html ${(page.length / 1024).toFixed(0)} KB, contract.mjs, ${readdirSync(examples).length} examples`)
